package codex

import (
	"context"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/chenhg5/cc-connect/config"
	"github.com/chenhg5/cc-connect/core"
)

// Only process startup/input and the messaging transport are replaced. Events
// are generated by the actual Codex parsers, then consumed by the real Engine.
type commentaryDeliverySession struct {
	events chan core.Event
	parse  func()
}

func (s *commentaryDeliverySession) Send(string, string, []core.ImageAttachment, []core.FileAttachment) error {
	s.parse()
	return nil
}
func (s *commentaryDeliverySession) RespondPermission(string, core.PermissionResult) error {
	return nil
}
func (s *commentaryDeliverySession) Events() <-chan core.Event { return s.events }
func (s *commentaryDeliverySession) CurrentSessionID() string  { return "commentary-delivery" }
func (s *commentaryDeliverySession) Alive() bool               { return true }
func (s *commentaryDeliverySession) Close() error              { return nil }

type commentaryDeliveryAgent struct{ session *commentaryDeliverySession }

func (a *commentaryDeliveryAgent) Name() string { return "codex" }
func (a *commentaryDeliveryAgent) StartSession(context.Context, string) (core.AgentSession, error) {
	return a.session, nil
}
func (a *commentaryDeliveryAgent) ListSessions(context.Context) ([]core.AgentSessionInfo, error) {
	return nil, nil
}
func (a *commentaryDeliveryAgent) Stop() error { return nil }

type commentaryDeliveryPlatform struct{ sent chan string }

func (p *commentaryDeliveryPlatform) Name() string                    { return "test" }
func (p *commentaryDeliveryPlatform) Start(core.MessageHandler) error { return nil }
func (p *commentaryDeliveryPlatform) Stop() error                     { return nil }
func (p *commentaryDeliveryPlatform) Send(_ context.Context, _ any, text string) error {
	p.sent <- text
	return nil
}
func (p *commentaryDeliveryPlatform) Reply(ctx context.Context, replyCtx any, text string) error {
	return p.Send(ctx, replyCtx, text)
}

func TestCodexCommentary_ProductionConfigPreservesNarration(t *testing.T) {
	t.Setenv("HOME", t.TempDir())
	for _, backend := range []string{"exec", "app_server"} {
		for _, phase := range []string{"", "commentary"} {
			for _, global := range []string{"absent", "false", "true"} {
				for _, project := range []string{"absent", "false", "true"} {
					t.Run(backend+"/phase="+phase+"/global="+global+"/project="+project, func(t *testing.T) {
						raw := "[display]\nmode = \"quiet\"\nreply_footer = false\nshow_context_indicator = false\n"
						if global != "absent" {
							raw += "commentary_messages = " + global + "\n"
						}
						raw += "[[projects]]\nname = \"commentary\"\n[projects.agent]\ntype = \"codex\"\n[[projects.platforms]]\ntype = \"test\"\n"
						if project != "absent" {
							raw += "[projects.display]\ncommentary_messages = " + project + "\n"
						}
						path := filepath.Join(t.TempDir(), "config.toml")
						if err := os.WriteFile(path, []byte(raw), 0600); err != nil {
							t.Fatal(err)
						}
						cfg, err := config.Load(path)
						if err != nil {
							t.Fatal(err)
						}
						proj := &cfg.Projects[0]
						enabled := config.EffectiveCommentaryMessages(cfg, proj)
						mode, thinking, tools, thinkingLen, toolLen, showContext, footer, hideFooter := config.EffectiveDisplay(cfg, proj)
						wantStandalone := global == "true"
						if project != "absent" {
							wantStandalone = project == "true"
						}
						s := &commentaryDeliverySession{events: make(chan core.Event, 16)}
						if backend == "exec" {
							parser := &codexSession{ctx: context.Background(), events: s.events}
							s.parse = func() {
								parser.handleItemCompleted(map[string]any{"item": map[string]any{"type": "reasoning", "summary": []any{map[string]any{"type": "summary_text", "text": "Private planning"}}}})
								parser.handleItemCompleted(map[string]any{"item": map[string]any{"type": "agent_message", "phase": phase, "text": "Working. "}})
								parser.handleItemStarted(map[string]any{"item": map[string]any{"type": "collab_tool_call", "tool": "spawn_agent", "receiver_thread_ids": []any{"child"}}})
								parser.handleItemCompleted(map[string]any{"item": map[string]any{"type": "agent_message", "phase": "final_answer", "text": "Done."}})
								parser.handleEvent(map[string]any{"type": "turn.completed"})
							}
						} else {
							parser := &appServerSession{ctx: context.Background(), events: s.events, currentTurn: "turn"}
							parser.threadID.Store("parent")
							s.parse = func() {
								parser.handleItemCompleted(map[string]any{"type": "reasoning", "summary": []any{"Private planning"}})
								parser.handleItemCompleted(map[string]any{"type": "agentMessage", "phase": phase, "text": "Working. "})
								parser.handleItemStarted(map[string]any{"type": "collabAgentToolCall", "tool": "spawnAgent", "receiverThreadIds": []any{"child"}})
								parser.handleItemCompleted(map[string]any{"type": "agentMessage", "phase": "final_answer", "text": "Done."})
								parser.handleNotification("turn/completed", []byte(`{"threadId":"parent","turn":{"id":"turn","status":"completed"}}`))
							}
						}
						p := &commentaryDeliveryPlatform{sent: make(chan string, 16)}
						e := core.NewEngine("commentary", &commentaryDeliveryAgent{session: s}, []core.Platform{p}, "", core.LangEnglish)
						defer func() { _ = e.Stop() }()
						// Production startup/reload always supplies a resolved non-nil pointer.
						e.SetDisplayConfig(core.DisplayCfg{
							Mode: mode, CardMode: config.EffectiveCardMode(cfg, proj),
							ThinkingMessages: thinking, ToolMessages: tools,
							ThinkingMaxLen: thinkingLen, ToolMaxLen: toolLen,
							CommentaryMessages: &enabled, HideAgentFooter: hideFooter,
						})
						e.SetStreamPreviewCfg(core.StreamPreviewCfg{Enabled: false})
						e.SetReplyFooterEnabled(footer)
						e.SetShowContextIndicator(showContext)
						e.ReceiveMessage(p, &core.Message{SessionKey: "test:commentary:user", Platform: "test", UserID: "user", Content: "Check work", ReplyCtx: "ctx"})
						var messages []string
						timer := time.NewTimer(3 * time.Second)
						defer timer.Stop()
						for {
							select {
							case text := <-p.sent:
								messages = append(messages, text)
								if strings.Contains(text, "Private planning") {
									t.Fatalf("private reasoning leaked: %q", messages)
								}
								if !strings.Contains(text, "Done.") {
									continue
								}
								if wantStandalone {
									if len(messages) != 2 || messages[0] != "Working." || text != "Done." {
										t.Fatalf("opt-in messages = %q", messages)
									}
								} else if len(messages) != 1 || text != "Working. Done." {
									t.Fatalf("legacy narration was lost or sent separately: %q", messages)
								}
								return
							case <-timer.C:
								t.Fatalf("no final answer: %q", messages)
							}
						}
					})
				}
			}
		}
	}
}
